namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Italian",
                ["400g spaghetti", "200g pancetta", "4 egg yolks", "100g Pecorino Romano", "Black pepper"],
                ["Cook spaghetti in salted boiling water until al dente.",
                 "Fry pancetta until crispy.",
                 "Whisk egg yolks with grated Pecorino and pepper.",
                 "Toss hot pasta with pancetta, then stir in egg mixture off heat.",
                 "Serve immediately with extra cheese."]),

            new(2, "Chicken Tikka Masala", "Indian",
                ["500g chicken breast", "200ml yogurt", "2 tbsp tikka paste", "400ml tomato sauce", "200ml cream", "Basmati rice"],
                ["Marinate chicken in yogurt and tikka paste for 1 hour.",
                 "Grill or pan-fry chicken until charred.",
                 "Simmer tomato sauce with cream and spices.",
                 "Add chicken to sauce and cook for 10 minutes.",
                 "Serve over basmati rice."]),

            new(3, "Caesar Salad", "American",
                ["1 romaine lettuce", "Croutons", "Parmesan cheese", "Caesar dressing", "2 anchovy fillets"],
                ["Wash and chop romaine lettuce.",
                 "Make dressing by blending anchovies, garlic, lemon juice, and olive oil.",
                 "Toss lettuce with dressing.",
                 "Top with croutons and shaved Parmesan."]),

            new(4, "Beef Tacos", "Mexican",
                ["500g ground beef", "Taco shells", "Lettuce", "Tomato", "Cheese", "Sour cream", "Taco seasoning"],
                ["Brown ground beef with taco seasoning.",
                 "Warm taco shells in oven.",
                 "Dice tomato and shred lettuce.",
                 "Fill shells with beef, lettuce, tomato, cheese, and sour cream."]),

            new(5, "Miso Soup", "Japanese",
                ["4 cups dashi stock", "3 tbsp miso paste", "200g tofu", "2 green onions", "Wakame seaweed"],
                ["Heat dashi stock until simmering.",
                 "Dissolve miso paste in a small amount of stock, then add back.",
                 "Add cubed tofu and rehydrated wakame.",
                 "Simmer gently — do not boil.",
                 "Serve topped with sliced green onions."]),

            new(6, "Chocolate Lava Cake", "Desserts",
                ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour"],
                ["Melt chocolate and butter together.",
                 "Whisk eggs with sugar until fluffy.",
                 "Fold chocolate mixture into eggs, then add flour.",
                 "Pour into greased ramekins.",
                 "Bake at 220°C for 12 minutes — center should be molten."]),
        };
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        _recipes.Add(recipe);
    }

    public int GetNextId() => _recipes.Max(r => r.Id) + 1;

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();
        _ratings[recipeId].Add(stars);
    }

    public (double Average, int Count) GetRating(int recipeId)
    {
        if (!_ratings.TryGetValue(recipeId, out var ratings) || ratings.Count == 0)
            return (0, 0);
        return (ratings.Average(), ratings.Count);
    }
}

public record Recipe(int Id, string Title, string Category, List<string> Ingredients, List<string> Steps);

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService Recipes

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="Rate @star star(s)">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    @if (_ratingCount > 0)
    {
        <span class="rating-summary">@_averageRating.ToString("0.0") avg (@_ratingCount ratings)</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int _selectedRating;
    private double _averageRating;
    private int _ratingCount;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        var (avg, count) = Recipes.GetRating(RecipeId);
        _averageRating = avg;
        _ratingCount = count;
    }

    private void Rate(int stars)
    {
        _selectedRating = stars;
        Recipes.AddRating(RecipeId, stars);
        var (avg, count) = Recipes.GetRating(RecipeId);
        _averageRating = avg;
        _ratingCount = count;
        _submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 4px;
    margin: 1rem 0;
}

.star {
    font-size: 1.8rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
    user-select: none;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

.rating-summary {
    margin-left: 0.5rem;
    font-size: 0.9rem;
    color: #666;
}

.rating-thanks {
    margin-left: 0.5rem;
    font-size: 0.85rem;
    color: #28a745;
    font-weight: 500;
}

