@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService Recipes

<PageTitle>@(CategoryName is not null ? $"{CategoryName} Recipes" : "All Categories") — RecipeHub</PageTitle>

@if (CategoryName is null)
{
    <h1>All Categories</h1>
    <div class="list-group">
        @foreach (var category in Recipes.GetCategories())
        {
            <a href="categories/@category" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                @category
                <span class="badge bg-primary rounded-pill">@Recipes.GetRecipesByCategory(category).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    var recipes = Recipes.GetRecipesByCategory(CategoryName);

    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">@recipe.Ingredients.Count ingredients · @recipe.Steps.Count steps</p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService Recipes

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@_recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item"><a href="categories/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <StarRating RecipeId="@_recipe.Id" />

    <h3>Ingredients</h3>
    <ul class="list-group mb-4">
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in _recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = Recipes.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@_model.Title</strong>" has been added.
        <a href="recipe/@_newRecipeId">View it here</a>.
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">— Select a category —</option>
                <option value="American">American</option>
                <option value="Desserts">Desserts</option>
                <option value="Indian">Indian</option>
                <option value="Italian">Italian</option>
                <option value="Japanese">Japanese</option>
                <option value="Mexican">Mexican</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var ingredients = _model.Ingredients!
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();
        var steps = _model.Steps!
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        _newRecipeId = Recipes.GetNextId();
        var recipe = new Recipe(_newRecipeId, _model.Title!, _model.Category!, ingredients, steps);
        Recipes.AddRecipe(recipe);
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string? Title { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string? Category { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string? Ingredients { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string? Steps { get; set; }
    }
}

